csapp-amdahl.solution:
def speedup(parts):
    rest = 1.0 - sum(a for a, _ in parts)
    return 1.0 / (rest + sum(a / k for a, k in parts))

csapp-y86-interpreter.solution:
def run_y86(program, mem):
    MASK = (1 << 64) - 1

    def signed(v):
        v &= MASK
        return v - (1 << 64) if v >> 63 else v

    labels, code = {}, []
    for line in program:
        line = line.strip()
        if line.endswith(":"):
            labels[line[:-1]] = len(code)
        else:
            code.append(line)
    R = collections.defaultdict(int)
    M = {a: signed(v) for a, v in mem}
    ZF, SF, OF = 1, 0, 0
    pc = steps = 0

    def reg(tok):
        return tok.strip().lstrip("%")

    def memop(tok):
        tok = tok.strip()
        d, r = tok.split("(")
        return (int(d) if d else 0), reg(r.rstrip(")"))

    def cond(op):
        if op == "jmp":
            return True
        return {"jle": (SF ^ OF) | ZF, "jl": SF ^ OF, "je": ZF, "jne": 1 - ZF,
                "jge": 1 - (SF ^ OF), "jg": (1 - (SF ^ OF)) & (1 - ZF)}[op] == 1

    while 0 <= pc < len(code) and steps < 100000:
        line = code[pc]
        steps += 1
        parts = line.split(None, 1)
        op = parts[0]
        args = [a.strip() for a in parts[1].split(",")] if len(parts) > 1 else []
        nxt = pc + 1
        if op == "halt":
            break
        elif op == "nop":
            pass
        elif op == "irmovq":
            R[reg(args[1])] = signed(int(args[0].lstrip("$")))
        elif op == "rrmovq":
            R[reg(args[1])] = R[reg(args[0])]
        elif op == "mrmovq":
            d, rb = memop(args[0])
            R[reg(args[1])] = M.get(R[rb] + d, 0)
        elif op == "rmmovq":
            d, rb = memop(args[1])
            M[R[rb] + d] = R[reg(args[0])]
        elif op in ("addq", "subq", "andq", "xorq"):
            a, b = R[reg(args[0])], R[reg(args[1])]
            if op == "addq":
                t = signed(b + a)
                OF = int((a < 0) == (b < 0) and (t < 0) != (a < 0))
            elif op == "subq":
                t = signed(b - a)
                OF = int((a < 0) != (b < 0) and (t < 0) != (b < 0))
            elif op == "andq":
                t, OF = b & a, 0
            else:
                t, OF = b ^ a, 0
            t = signed(t)
            ZF, SF = int(t == 0), int(t < 0)
            R[reg(args[1])] = t
        elif op in ("jmp", "jle", "jl", "je", "jne", "jge", "jg"):
            if cond(op):
                nxt = labels[args[0]]
        elif op == "pushq":
            v = R[reg(args[0])]
            R["rsp"] = signed(R["rsp"] - 8)
            M[R["rsp"]] = v
        elif op == "popq":
            v = M.get(R["rsp"], 0)
            R["rsp"] = signed(R["rsp"] + 8)
            R[reg(args[0])] = v
        elif op == "call":
            R["rsp"] = signed(R["rsp"] - 8)
            M[R["rsp"]] = pc + 1
            nxt = labels[args[0]]
        elif op == "ret":
            nxt = M.get(R["rsp"], 0)
            R["rsp"] = signed(R["rsp"] + 8)
        pc = nxt
    return [R["rax"], steps]

csapp-pipeline-penalties.solution:
def pipeline_cycles(trace):
    if not trace:
        return [0, 0]
    bubbles = 0
    prev = None
    for kind, dst, srcs in trace:
        if prev and prev[0] == "load" and prev[1] and prev[1] in srcs:
            bubbles += 1
        if kind == "jmp_miss":
            bubbles += 2
        elif kind == "ret":
            bubbles += 3
        prev = (kind, dst)
    return [len(trace) + 4 + bubbles, bubbles]

csapp-critical-path.solution:
def loop_cycles(ops, n):
    ready = {}
    finish = 0
    for _ in range(n):
        for dst, lat, srcs in ops:
            t = lat
            for s in srcs:
                t = max(t, ready.get(s, 0) + lat)
            ready[dst] = t
            if t > finish:
                finish = t
    return finish

csapp-direct-mapped-cache.solution:
def direct_mapped(s, b, trace):
    lines = [None] * (1 << s)
    hits = misses = 0
    mask = (1 << s) - 1
    for a in trace:
        idx = (a >> b) & mask
        tag = a >> (s + b)
        if lines[idx] == tag:
            hits += 1
        else:
            misses += 1
            lines[idx] = tag
    return [hits, misses]

csapp-symbol-resolution.solution:
def resolve(modules):
    strong, weak, names = {}, {}, set()
    for i, m in enumerate(modules):
        for name, kind in m:
            names.add(name)
            if kind == "strong":
                strong.setdefault(name, []).append(i)
            elif kind == "weak":
                weak.setdefault(name, []).append(i)
    dup = sorted(n for n, lst in strong.items() if len(lst) > 1)
    if dup:
        return "multiple definition of " + dup[0]
    undef = sorted(n for n in names if n not in strong and n not in weak)
    if undef:
        return "undefined reference to " + undef[0]
    return [[n, strong[n][0] if n in strong else min(weak[n])] for n in sorted(names)]

csapp-twos-encode.solution:
def t2b(x, w):
    if not (-(1 << (w - 1)) <= x <= (1 << (w - 1)) - 1):
        return "overflow"
    return format(x & ((1 << w) - 1), "0%db" % w)

csapp-sign-extend.solution:
def sign_extend(p, from_w, to_w):
    if (p >> (from_w - 1)) & 1:
        p |= ((1 << to_w) - 1) ^ ((1 << from_w) - 1)
    return p

csapp-tadd-overflow.solution:
def tadd(x, y, w):
    true = x + y
    s = true & ((1 << w) - 1)
    if s >> (w - 1):
        s -= 1 << w
    if true > (1 << (w - 1)) - 1:
        kind = "positive"
    elif true < -(1 << (w - 1)):
        kind = "negative"
    else:
        kind = "none"
    return [s, kind]

csapp-float-decode.solution:
def decode_float(u):
    s = u >> 31
    e = (u >> 23) & 0xFF
    f = u & 0x7FFFFF
    if e == 0xFF:
        if f:
            return "nan"
        return "-inf" if s else "inf"
    if e == 0:
        v = f * 2.0 ** (-149)
    else:
        v = (f + (1 << 23)) * 2.0 ** (e - 150)
    return -v if s else v

csapp-float-round-even.solution:
def round_even(num, k):
    ip, fp = num.split(".")
    fp = fp + "0" * max(0, k - len(fp))
    kept = int(ip + fp[:k], 2)
    rest = fp[k:]
    if rest and rest[0] == "1":
        if "1" in rest[1:] or (kept & 1):
            kept += 1
    s = bin(kept)[2:]
    if k == 0:
        return s
    s = s.rjust(k + 1, "0")
    return s[:-k] + "." + s[-k:]

csapp-fork-count.solution:
def fork_count(ops):
    parents, children = 1, 0
    lines, created = 0, 1
    for op in ops:
        total = parents + children
        if op == "fork":
            parents, children = total, total
            created += total
        elif op == "print":
            lines += total
        elif op == "exit_if_child":
            children = 0
    return [lines, created]

csapp-page-translate.solution:
def translate(page_size, page_table, addrs):
    p = page_size.bit_length() - 1
    out = []
    for va in addrs:
        vpn, vpo = va >> p, va & (page_size - 1)
        if vpn >= len(page_table) or page_table[vpn] < 0:
            out.append(-1)
        else:
            out.append((page_table[vpn] << p) | vpo)
    return out

csapp-first-fit-malloc.solution:
def simulate_heap(heap_size, ops):
    blocks = [[0, heap_size, False]] if heap_size > 0 else []
    result_of = {}
    out = []
    for idx, (kind, arg) in enumerate(ops):
        if kind == "malloc":
            res = -1
            if arg > 0:
                asize = max(16, (arg + 8 + 7) // 8 * 8)
                for i, b in enumerate(blocks):
                    if not b[2] and b[1] >= asize:
                        if b[1] - asize >= 16:
                            blocks.insert(i + 1, [b[0] + asize, b[1] - asize, False])
                            b[1] = asize
                        b[2] = True
                        res = b[0]
                        break
            result_of[idx] = res
            out.append(res)
        else:
            start = result_of[arg]
            if start < 0:
                continue
            i = next(k for k, b in enumerate(blocks) if b[0] == start)
            blocks[i][2] = False
            if i + 1 < len(blocks) and not blocks[i + 1][2]:
                blocks[i][1] += blocks.pop(i + 1)[1]
            if i > 0 and not blocks[i - 1][2]:
                blocks[i - 1][1] += blocks.pop(i)[1]
    return out

csapp-fd-sharing.solution:
def run_io(files, ops):
    fdt = {}
    out = []

    def lowest():
        fd = 3
        while fd in fdt:
            fd += 1
        return fd

    for op in ops:
        kind = op[0]
        if kind == "open":
            if op[1] not in files:
                out.append(-1)
                continue
            fd = lowest()
            fdt[fd] = {"name": op[1], "pos": 0}
            out.append(fd)
        elif kind == "read":
            fd, n = op[1], op[2]
            if fd not in fdt:
                out.append(-1)
                continue
            e = fdt[fd]
            data = files[e["name"]][e["pos"]:e["pos"] + max(0, n)]
            e["pos"] += len(data)
            out.append(data)
        elif kind == "dup2":
            old, new = op[1], op[2]
            if old not in fdt:
                out.append(-1)
            else:
                fdt[new] = fdt[old]
                out.append(new)
        elif kind == "dup":
            if op[1] not in fdt:
                out.append(-1)
            else:
                fd = lowest()
                fdt[fd] = fdt[op[1]]
                out.append(fd)
        elif kind == "close":
            if op[1] in fdt:
                del fdt[op[1]]
                out.append(0)
            else:
                out.append(-1)
    return out

csapp-dotted-decimal.solution:
def convert(s):
    if s.startswith("0x"):
        try:
            v = int(s, 16)
        except ValueError:
            return "error"
        if v >= 1 << 32:
            return "error"
        return ".".join(str((v >> sh) & 0xFF) for sh in (24, 16, 8, 0))
    parts = s.split(".")
    if len(parts) != 4:
        return "error"
    v = 0
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return "error"
        v = (v << 8) | int(p)
    return "0x%x" % v

csapp-race-outcomes.solution:
def race_outcomes(n1, n2):
    end = (3 * n1, 3 * n2)
    start = (0, 0, 0, 0, 0)  # pc1, reg1, pc2, reg2, cnt
    seen = {start}
    stack = [start]
    finals = set()
    while stack:
        pc1, r1, pc2, r2, cnt = stack.pop()
        if pc1 == end[0] and pc2 == end[1]:
            finals.add(cnt)
            continue
        nxt = []
        if pc1 < end[0]:
            ph = pc1 % 3
            if ph == 0:
                nxt.append((pc1 + 1, cnt, pc2, r2, cnt))
            elif ph == 1:
                nxt.append((pc1 + 1, r1 + 1, pc2, r2, cnt))
            else:
                nxt.append((pc1 + 1, 0, pc2, r2, r1))
        if pc2 < end[1]:
            ph = pc2 % 3
            if ph == 0:
                nxt.append((pc1, r1, pc2 + 1, cnt, cnt))
            elif ph == 1:
                nxt.append((pc1, r1, pc2 + 1, r2 + 1, cnt))
            else:
                nxt.append((pc1, r1, pc2 + 1, 0, r2))
        for s in nxt:
            if s not in seen:
                seen.add(s)
                stack.append(s)
    return sorted(finals)

csapp-deadlock-check.solution:
def can_deadlock(threads):
    n = len(threads)
    lens = [len(t) for t in threads]

    def sem_values(pcs):
        vals = collections.defaultdict(lambda: 1)
        for t, pc in zip(threads, pcs):
            for op, name in t[:pc]:
                vals[name] += -1 if op == "P" else 1
        return vals

    start = tuple([0] * n)
    seen = {start}
    stack = [start]
    while stack:
        pcs = stack.pop()
        if all(pcs[i] == lens[i] for i in range(n)):
            continue
        vals = sem_values(pcs)
        moved = False
        for i in range(n):
            if pcs[i] == lens[i]:
                continue
            op, name = threads[i][pcs[i]]
            if op == "P" and vals[name] <= 0:
                continue
            moved = True
            nxt = pcs[:i] + (pcs[i] + 1,) + pcs[i + 1:]
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
        if not moved:
            return True
    return False
